import{_ as s,C as n,o as e,c as o,a2 as t,b as c,w as d,a as i,E as l,a3 as v}from"./chunks/framework.CZqXuAiL.js";const y=JSON.parse(`{"title":"Glacier Pack for Pterodactyl","description":"A family of 24 standalone addons for Pterodactyl Panel v1.12.x plus the Glacier Pack hub — a single custom admin dashboard that hosts every addon's complete management UI in one Glacier-styled page.","frontmatter":{"title":"Glacier Pack for Pterodactyl","description":"A family of 24 standalone addons for Pterodactyl Panel v1.12.x plus the Glacier Pack hub — a single custom admin dashboard that hosts every addon's complete management UI in one Glacier-styled page."},"headers":[],"relativePath":"glacier-pack/index.md","filePath":"glacier-pack/index.md","lastUpdated":1786286622000}`),h={name:"glacier-pack/index.md"};function g(p,a,u,m,f,k){const r=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="glacier-pack-for-pterodactyl" tabindex="-1" data-v-37edc472>Glacier Pack for Pterodactyl <a class="header-anchor" href="#glacier-pack-for-pterodactyl" aria-label="Permalink to &quot;Glacier Pack for Pterodactyl&quot;" data-v-37edc472>​</a></h1><p data-v-37edc472><strong data-v-37edc472>A family of 24 standalone addons for Pterodactyl Panel v1.12.x, managed from one hub.</strong> Glacier Pack installs as self-contained packages — no Blueprint, no module daemons on your nodes — and replaces the sprawl of 24 separate admin pages with a single custom dashboard at <code data-v-37edc472>/admin/glacier-pack</code> that hosts every addon&#39;s complete management UI in one Glacier-styled page.</p><div class="tip custom-block" style="margin-top:1.5rem;" data-v-37edc472><p data-v-37edc472><strong data-v-37edc472>Built for PingLess Studios</strong><a href="https://studio.pingless.org" target="_blank" rel="noreferrer" data-v-37edc472>studio.pingless.org</a> · Standalone packages, installed directly on the panel</p></div><hr data-v-37edc472><h2 id="architecture" tabindex="-1" data-v-37edc472>Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;" data-v-37edc472>​</a></h2>',5)),(e(),c(v,null,{default:d(()=>[l(r,{id:"mermaid-15",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Pack%5B%22Glacier%20Addons%20family%20(23%20addons)%22%5D%0A%20%20%20%20%20%20%20%20BASIC%5B%22Basic%20pack%3Cbr%2F%3E9%20addons%22%5D%0A%20%20%20%20%20%20%20%20ADV%5B%22Advanced%20pack%3Cbr%2F%3E14%20addons%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Panel%5B%22Pterodactyl%20Panel%20v1.12.x%22%5D%0A%20%20%20%20%20%20%20%20HUB%5B%22Glacier%20Pack%20hub%3Cbr%2F%3E%2Fadmin%2Fglacier-pack%22%5D%0A%20%20%20%20%20%20%20%20EP%5B%22Addon%20action%20endpoints%3Cbr%2F%3EPOST%20%2F%20DELETE%20routes%22%5D%0A%20%20%20%20%20%20%20%20CLIENT%5B%22Client-facing%20surfaces%3Cbr%2F%3Econsole%20%C2%B7%20files%20%C2%B7%20account%20%C2%B7%20network%22%5D%0A%20%20%20%20%20%20%20%20BASIC%20--%3E%20HUB%0A%20%20%20%20%20%20%20%20ADV%20--%3E%20HUB%0A%20%20%20%20%20%20%20%20HUB%20--%3E%7C%22_hub%20return%20URL%22%7C%20EP%0A%20%20%20%20%20%20%20%20BASIC%20--%3E%20CLIENT%0A%20%20%20%20%20%20%20%20ADV%20--%3E%20CLIENT%0A%20%20%20%20end%0A%0A%20%20%20%20ADMIN%5B%22Root%20admin%22%5D%20--%3E%7Cone%20sidebar%20tab%7C%20HUB%0A%20%20%20%20USERS%5B%22Panel%20users%22%5D%20--%3E%20CLIENT%0A"})]),fallback:d(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p data-v-37edc472>The hub is the <strong data-v-37edc472>only admin surface</strong>. Each addon&#39;s original admin pages and sidebar links are removed on install; everything an admin could do there — every table, form, action, filter and stat — renders inside a hub pane instead. Forms still post to each addon&#39;s own endpoints and land back on the same pane, so nothing about how the addons work changes — only where you manage them.</p><hr data-v-37edc472><h2 id="key-features" tabindex="-1" data-v-37edc472>Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;" data-v-37edc472>​</a></h2><ul data-v-37edc472><li data-v-37edc472><strong data-v-37edc472>One admin dashboard for everything.</strong> A single &quot;Glacier Pack&quot; sidebar tab opens a standalone, full-page admin UI styled after the Glacier theme editor — near-black surfaces, teal accent, its own chrome (not AdminLTE). Root-admin only, guarded twice.</li><li data-v-37edc472><strong data-v-37edc472>23 addons, two packs.</strong> The Basic pack covers panel operations (recycle bin, URL downloads, logs, alerts, uptime); the Advanced pack covers hosting workflows (S3 backups, plugin/mod/modpack installers, staff delegation, subdomains, server imports).</li><li data-v-37edc472><strong data-v-37edc472>Full pages in-hub, not summaries.</strong> Each addon renders its complete original UI as a hub pane — tables, forms, pagination, stat cards — with pill-style sub-tabs for multi-page addons.</li><li data-v-37edc472><strong data-v-37edc472>Uniform save flow.</strong> Every form carries a <code data-v-37edc472>_hub</code> return URL; successful saves land back on the same pane with a success banner, and validation errors render in a hub-styled callout above the form.</li><li data-v-37edc472><strong data-v-37edc472>Standalone packaging, zero framework dependencies.</strong> Every addon is a self-contained directory that mirrors the panel root (<code data-v-37edc472>PanelFiles/</code>) with an idempotent <code data-v-37edc472>data/install.sh</code> installer — no Blueprint, no external CDN assets, no core-file replacement (marker-delimited patches only).</li><li data-v-37edc472><strong data-v-37edc472>Client surfaces without rebuilds.</strong> 20 of 23 addons ship their client UI as static JS/CSS — no <code data-v-37edc472>yarn build</code>. The panel&#39;s React app is enhanced, never forked.</li><li data-v-37edc472><strong data-v-37edc472>Glacier theme compatible.</strong> Client-facing addon styles consume Glacier design tokens (<code data-v-37edc472>var(--gl-*, fallback)</code>), so every addon inherits Glacier&#39;s accent, surfaces and radius when the theme is installed — and keeps its own look when it isn&#39;t.</li><li data-v-37edc472><strong data-v-37edc472>Safe delegation built in.</strong> Permission Manager gives staff a restricted admin area at <code data-v-37edc472>/admin/staff</code> with real, auto-provisioned Pterodactyl subusers — no <code data-v-37edc472>root_admin</code> grants, enforced by the panel itself.</li><li data-v-37edc472><strong data-v-37edc472>Idempotent installers.</strong> Every <code data-v-37edc472>install.sh</code> is safe to re-run (and should be re-run after panel updates overwrite patched files), registers one service provider, runs migrations, and clears caches.</li></ul><hr data-v-37edc472><h2 id="quick-install" tabindex="-1" data-v-37edc472>Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;" data-v-37edc472>​</a></h2><p data-v-37edc472>Install the hub first — it is the only admin surface for the whole family:</p><div class="language-bash vp-adaptive-theme" data-v-37edc472><button title="Copy Code" class="copy" data-v-37edc472></button><span class="lang" data-v-37edc472>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-37edc472><code data-v-37edc472><span class="line" data-v-37edc472><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-37edc472>cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-37edc472> glacier-pack</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-37edc472> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-37edc472>sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-37edc472> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-37edc472> data/install.sh</span></span></code></pre></div><p data-v-37edc472>Then install any addon the same way:</p><div class="language-bash vp-adaptive-theme" data-v-37edc472><button title="Copy Code" class="copy" data-v-37edc472></button><span class="lang" data-v-37edc472>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-37edc472><code data-v-37edc472><span class="line" data-v-37edc472><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-37edc472>cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-37edc472> recycle-bin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" data-v-37edc472> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-37edc472>sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-37edc472> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-37edc472> data/install.sh</span></span></code></pre></div><p data-v-37edc472>Open <strong data-v-37edc472>Admin → Glacier Pack</strong> (or <code data-v-37edc472>/admin/glacier-pack</code>) as a root admin. See <a href="./getting-started/installation" data-v-37edc472>Installation</a> for prerequisites, verification and troubleshooting.</p><hr data-v-37edc472><h2 id="pack-contents" tabindex="-1" data-v-37edc472>Pack Contents <a class="header-anchor" href="#pack-contents" aria-label="Permalink to &quot;Pack Contents&quot;" data-v-37edc472>​</a></h2><h3 id="basic-pack-—-9-addons" tabindex="-1" data-v-37edc472>Basic pack — 9 addons <a class="header-anchor" href="#basic-pack-—-9-addons" aria-label="Permalink to &quot;Basic pack — 9 addons&quot;" data-v-37edc472>​</a></h3><table tabindex="0" data-v-37edc472><thead data-v-37edc472><tr data-v-37edc472><th data-v-37edc472>Addon</th><th data-v-37edc472>Purpose</th></tr></thead><tbody data-v-37edc472><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Config Editor</strong></td><td data-v-37edc472>Edit the panel&#39;s <code data-v-37edc472>.env</code> safely from the browser, with backups and validation.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Console Log Share</strong></td><td data-v-37edc472>One-click console log copying and sharing from the server console.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Login Activity</strong></td><td data-v-37edc472>Filterable record of every successful sign-in to the panel.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Move Files</strong></td><td data-v-37edc472>Browsable directory picker for the file manager move/copy dialog.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Node Status</strong></td><td data-v-37edc472>Per-server uptime graphs, incident logs, and node health tracking.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Panel Logs</strong></td><td data-v-37edc472>Live view of the panel&#39;s own log files, no SSH session required.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Recycle Bin</strong></td><td data-v-37edc472>Recoverable file deletion with quotas and per-egg retention windows.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Resource Alerts</strong></td><td data-v-37edc472>Threshold notifications the moment a server crosses a usage limit.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>URL Download</strong></td><td data-v-37edc472>Fetch remote files straight into a server from the file manager.</td></tr></tbody></table><h3 id="advanced-pack-—-14-addons" tabindex="-1" data-v-37edc472>Advanced pack — 14 addons <a class="header-anchor" href="#advanced-pack-—-14-addons" aria-label="Permalink to &quot;Advanced pack — 14 addons&quot;" data-v-37edc472>​</a></h3><table tabindex="0" data-v-37edc472><thead data-v-37edc472><tr data-v-37edc472><th data-v-37edc472>Addon</th><th data-v-37edc472>Purpose</th></tr></thead><tbody data-v-37edc472><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Backup Pro</strong></td><td data-v-37edc472>Scheduled server backups to S3-compatible storage with a full restore flow.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Database Manager</strong></td><td data-v-37edc472>Import and export for panel-managed server MySQL databases.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Mod Installer</strong></td><td data-v-37edc472>Browse and install Minecraft mods from Modrinth and CurseForge.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Modpack Installer</strong></td><td data-v-37edc472>One-click Modrinth and CurseForge modpack installs from the file manager.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Node Stats</strong></td><td data-v-37edc472>Node analytics: historical tracking, capacity planning, and forecasting.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Permission Manager</strong></td><td data-v-37edc472>Staff roles with a restricted admin area — no <code data-v-37edc472>root_admin</code> required.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Player List</strong></td><td data-v-37edc472>Live online-player list with a count badge on the server console.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Player Manager</strong></td><td data-v-37edc472>Manage Minecraft Java players over plain RCON, nothing on the node.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Plugin Installer</strong></td><td data-v-37edc472>Browse, install, and manage Minecraft plugins from live catalogues.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Server Importer</strong></td><td data-v-37edc472>Move servers from another Pterodactyl panel via the source&#39;s Application API.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Server Properties</strong></td><td data-v-37edc472>Friendly, categorized server.properties editor for Minecraft servers.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Staff Requests</strong></td><td data-v-37edc472>Users request server access from each other with owner approval.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Subdomain Manager</strong></td><td data-v-37edc472>Self-service DNS A and SRV subdomains for game servers.</td></tr><tr data-v-37edc472><td data-v-37edc472><strong data-v-37edc472>Version Changer</strong></td><td data-v-37edc472>Change the Minecraft: Java Edition version of a server from the panel.</td></tr></tbody></table><hr data-v-37edc472><h2 id="works-with-the-glacier-theme" tabindex="-1" data-v-37edc472>Works with the Glacier theme <a class="header-anchor" href="#works-with-the-glacier-theme" aria-label="Permalink to &quot;Works with the Glacier theme&quot;" data-v-37edc472>​</a></h2><p data-v-37edc472>Every addon&#39;s client-facing UI is <strong data-v-37edc472>Glacier-compatible</strong>: styles reference the theme&#39;s design tokens through <code data-v-37edc472>var(--gl-*, fallback)</code> chains, so with the <a href="./../glacier/" data-v-37edc472>Glacier theme</a> installed, addon surfaces inherit its accent color, surfaces, borders and radius automatically — in both dark and light mode. Without Glacier, the fallback values render each addon&#39;s own standalone look, pixel-identical to how it shipped. Nothing is required, nothing breaks either way.</p><div class="info custom-block" data-v-37edc472><p class="custom-block-title" data-v-37edc472>INFO</p><p data-v-37edc472>Glacier compatibility applies to <strong data-v-37edc472>client-facing</strong> surfaces only (server pages, account area, login page). The hub and the admin area are styled by the hub&#39;s own stylesheet, independent of any theme.</p></div><hr data-v-37edc472><h2 id="next-steps" tabindex="-1" data-v-37edc472>Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;" data-v-37edc472>​</a></h2><ul data-v-37edc472><li data-v-37edc472><strong data-v-37edc472><a href="./getting-started/installation" data-v-37edc472>Installation →</a></strong> — prerequisites, hub install, per-addon install, verify, uninstall.</li><li data-v-37edc472><strong data-v-37edc472><a href="./getting-started/quick-start" data-v-37edc472>Quick Start →</a></strong> — hub plus three starter addons in minutes.</li><li data-v-37edc472><strong data-v-37edc472><a href="./configuration/reference" data-v-37edc472>Configuration Reference →</a></strong> — every setting, every default, per addon.</li><li data-v-37edc472><strong data-v-37edc472><a href="./user-guide/dashboard" data-v-37edc472>The Hub Dashboard →</a></strong> — a tour of the unified admin UI.</li><li data-v-37edc472><strong data-v-37edc472><a href="./architecture/overview" data-v-37edc472>Architecture →</a></strong> — how the packaging format and hub contract work.</li></ul><hr data-v-37edc472><div class="footer-note" data-v-37edc472><p data-v-37edc472><strong data-v-37edc472>Developed for <a href="https://studio.pingless.org" target="_blank" rel="noreferrer" data-v-37edc472>PingLess Studios</a></strong></p><p data-v-37edc472>Questions or licensing — reach us at <a href="https://studio.pingless.org" target="_blank" rel="noreferrer" data-v-37edc472>studio.pingless.org</a>.</p></div>',26))])}const P=s(h,[["render",g],["__scopeId","data-v-37edc472"]]);export{y as __pageData,P as default};
